import{_ as e,o,c as d,a5 as n}from"./chunks/framework.CsGesDJn.js";const y=JSON.parse('{"title":"Test — Chế độ Không gian Cá nhân & Tác giả Độc lập (Hybrid Personal Studio + Solo Workspace Mode)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/personal-workspace-mode/test.md","filePath":"feature/personal-workspace-mode/test.md"}'),c={name:"feature/personal-workspace-mode/test.md"};function l(a,t,s,i,r,g){return o(),d("div",null,[...t[0]||(t[0]=[n('<h1 id="test-—-che-đo-khong-gian-ca-nhan-tac-gia-đoc-lap-hybrid-personal-studio-solo-workspace-mode" tabindex="-1">Test — Chế độ Không gian Cá nhân &amp; Tác giả Độc lập (Hybrid Personal Studio + Solo Workspace Mode) <a class="header-anchor" href="#test-—-che-đo-khong-gian-ca-nhan-tac-gia-đoc-lap-hybrid-personal-studio-solo-workspace-mode" aria-label="Permalink to &quot;Test — Chế độ Không gian Cá nhân &amp; Tác giả Độc lập (Hybrid Personal Studio + Solo Workspace Mode)&quot;">​</a></h1><p>&gt; Bước ④ theo <code>docs/rule/feature-workflow.md</code>. Dựa trên <code>spec.md</code> (AC1–AC18, §10, §11, §13), <code>plan.md</code>, <code>task.md</code>. &gt; Cột <strong>Map</strong> đối chiếu trực tiếp tới AC / mục spec / đầu việc <code>task.md</code>. &gt; Tầng kiểm thử: <strong>U</strong> = Unit Test, <strong>I</strong> = Integration Test (MockMvc + Mongo/Postgres), <strong>E</strong> = E2E / Web Component Test, <strong>M</strong> = Mobile Test, <strong>T</strong> = Kiểm tra Giao diện Sáng/Tối, Responsive &amp; Đa ngôn ngữ.</p><hr><h2 id="du-lieu-chuan-bi-kiem-thu-test-fixtures" tabindex="-1">Dữ liệu Chuẩn bị Kiểm thử (Test Fixtures) <a class="header-anchor" href="#du-lieu-chuan-bi-kiem-thu-test-fixtures" aria-label="Permalink to &quot;Dữ liệu Chuẩn bị Kiểm thử (Test Fixtures)&quot;">​</a></h2><ul><li><strong>Người dùng</strong>: <ul><li><code>soloUser</code>: Người dùng mới đăng ký, chưa có Agency hay Workspace nào.</li><li><code>hybridUser</code>: Người dùng đang là <code>Creator</code> tại <code>Agency A1</code> (công ty B2B), đồng thời muốn mở <code>Personal Studio</code> riêng.</li><li><code>teammateCreator</code>: Bạn cùng nhóm được mời vào Workspace <code>PERSONAL</code> của <code>soloUser</code> với vai trò <code>Creator</code>.</li><li><code>agencyOwner</code>: Chủ sở hữu <code>Agency A1</code> (<code>Owner</code>).</li><li><code>activeClient</code>: Khách hàng (<code>Client</code>) đang hoạt động trong <code>Workspace W_AGENCY</code> thuộc <code>Agency A1</code>.</li></ul></li><li><strong>Không gian làm việc (<code>Workspace</code>)</strong>: <ul><li><code>W_PERSONAL</code>: Workspace được tạo qua <code>/api/v1/workspaces/personal/bootstrap</code> (<code>workspaceMode = &quot;PERSONAL&quot;</code>).</li><li><code>W_LEGACY</code>: Workspace cũ trong DB có <code>settings = &quot;{}&quot;</code> (chưa có trường <code>workspaceMode</code>).</li><li><code>W_AGENCY</code>: Workspace B2B có <code>workspaceMode = &quot;AGENCY&quot;</code> và đang có <code>activeClient</code>.</li></ul></li></ul><hr><h2 id="a-khoi-tao-khong-gian-ca-nhan-bootstrap-quan-ly-workspacemode" tabindex="-1">A. Khởi tạo Không gian Cá nhân (<code>Bootstrap</code>) &amp; Quản lý <code>workspaceMode</code> <a class="header-anchor" href="#a-khoi-tao-khong-gian-ca-nhan-bootstrap-quan-ly-workspacemode" aria-label="Permalink to &quot;A. Khởi tạo Không gian Cá nhân (`Bootstrap`) &amp; Quản lý `workspaceMode`&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">ID</th><th style="text-align:left;">Map</th><th style="text-align:center;">Tầng</th><th style="text-align:left;">Bước / Input</th><th style="text-align:left;">Kết quả mong đợi</th><th style="text-align:center;">KQ</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>P-A1</strong></td><td style="text-align:left;">AC1, §7.1, T1.5</td><td style="text-align:center;">U+I</td><td style="text-align:left;"><code>soloUser</code> gọi <code>POST /api/v1/workspaces/personal/bootstrap</code> lần đầu tiên (body rỗng hoặc <code>{ &quot;name&quot;: &quot;Kênh Cá Nhân&quot; }</code>)</td><td style="text-align:left;">Tạo thành công 1 <code>Agency</code> cá nhân (<code>logoIcon = &quot;personal-studio&quot;</code>, <code>ownerId = soloUser.id</code>), khởi tạo ví AI Credit + gói <code>Basic</code>, tạo 1 <code>Workspace</code> (<code>workspaceMode = &quot;PERSONAL&quot;</code>, <code>isPersonalDefault = true</code>), gán <code>soloUser</code> làm <code>MANAGER</code>, trả về <code>200 OK</code>.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-A2</strong></td><td style="text-align:left;">AC1, §11.1, T1.5</td><td style="text-align:center;">U+I</td><td style="text-align:left;"><code>soloUser</code> gọi lại <code>POST /api/v1/workspaces/personal/bootstrap</code> lần thứ 2 (hoặc bấm đúp 2 request liên tiếp)</td><td style="text-align:left;">Trả về đúng <code>W_PERSONAL</code> đã tạo ở P-A1 (<code>id</code> giữ nguyên), tuyệt đối không tạo thêm <code>Agency</code> hay <code>Workspace</code> trùng lặp (Idempotent 100%).</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-A3</strong></td><td style="text-align:left;">AC2, §11.2, T1.2</td><td style="text-align:center;">U</td><td style="text-align:left;">Đọc <code>W_LEGACY</code> có <code>settings = &quot;{}&quot;</code>, <code>settings = null</code> hoặc chuỗi JSON không hợp lệ qua <code>WorkspaceSettingsHelper.extractMode</code></td><td style="text-align:left;">Luôn trả về <code>WorkspaceMode.AGENCY</code>, không ném ngoại lệ, không làm thay đổi hành vi của các Workspace cũ.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-A4</strong></td><td style="text-align:left;">§11.3, T1.2</td><td style="text-align:center;">U</td><td style="text-align:left;"><code>Workspace</code> có <code>settings = {&quot;customTheme&quot;:&quot;warm&quot;,&quot;notifyEmail&quot;:true}</code>; gọi <code>WorkspaceSettingsHelper.writeMode(..., PERSONAL, false)</code></td><td style="text-align:left;">JSON sau khi lưu có <code>&quot;workspaceMode&quot;:&quot;PERSONAL&quot;</code> đồng thời giữ nguyên <code>&quot;customTheme&quot;:&quot;warm&quot;</code> và <code>&quot;notifyEmail&quot;:true</code>.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-A5</strong></td><td style="text-align:left;">AC3, §7.2, T1.4</td><td style="text-align:center;">I</td><td style="text-align:left;"><code>agencyOwner</code> gọi <code>POST /api/v1/agencies/{id}/workspaces</code> với <code>workspaceMode = &quot;PERSONAL&quot;</code>, <code>managerId = null</code>, <code>brandName = null</code></td><td style="text-align:left;">Backend tự động gán <code>managerId = agencyOwner.id</code>, <code>brandName = name</code> và lưu <code>workspaceMode = &quot;PERSONAL&quot;</code>, trả về <code>201 Created</code>.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-A6</strong></td><td style="text-align:left;">AC4, §7.2, T1.6</td><td style="text-align:center;">I</td><td style="text-align:left;">Chủ không gian gọi <code>PUT /api/v1/workspaces/{W_PERSONAL}</code> với <code>workspaceMode = &quot;AGENCY&quot;</code> sau khi đã tạo 3 Task và 1 Chiến dịch</td><td style="text-align:left;">Chuyển thành công sang <code>workspaceMode = &quot;AGENCY&quot;</code>; toàn bộ Chiến dịch, Task, Bài viết, Tư liệu và cấu hình MXH được bảo toàn 100%.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-A7</strong></td><td style="text-align:left;">AC5, §10, §11.5, T1.6</td><td style="text-align:center;">I</td><td style="text-align:left;"><code>agencyOwner</code> gọi <code>PUT /api/v1/workspaces/{W_AGENCY}</code> đổi <code>workspaceMode</code> từ <code>&quot;AGENCY&quot;</code> sang <code>&quot;PERSONAL&quot;</code> khi đang có <code>activeClient</code> (<code>ACTIVE</code>)</td><td style="text-align:left;">Bị từ chối với HTTP <code>409 Conflict</code>, mã lỗi <code>WORKSPACE_MODE_SWITCH_BLOCKED_BY_ACTIVE_CLIENT</code>.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-A8</strong></td><td style="text-align:left;">AC4, T1.6</td><td style="text-align:center;">I</td><td style="text-align:left;">Trong một Workspace <code>AGENCY</code> <strong>chưa có</strong> <code>Client</code> nào hoạt động, <code>agencyOwner</code> đổi <code>workspaceMode</code> sang <code>&quot;PERSONAL&quot;</code></td><td style="text-align:left;">Cập nhật thành công sang <code>workspaceMode = &quot;PERSONAL&quot;</code>.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-A9</strong></td><td style="text-align:left;">§11.6, T1.5</td><td style="text-align:center;">I</td><td style="text-align:left;"><code>soloUser</code> xóa/archive <code>W_PERSONAL</code> cũ rồi gọi lại <code>POST /api/v1/workspaces/personal/bootstrap</code></td><td style="text-align:left;">Hệ thống tái sử dụng <code>Personal Hub Agency</code> cũ (giữ nguyên ví AI Credit) và tạo 1 <code>Workspace</code> <code>PERSONAL</code> mới đang <code>ACTIVE</code>.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-A10</strong></td><td style="text-align:left;">US7, §11.12, T1.5</td><td style="text-align:center;">I+E</td><td style="text-align:left;"><code>hybridUser</code> (đang là <code>Creator</code> ở <code>Agency A1</code>) bấm <strong>&quot;Không gian Cá nhân (Personal Studio)&quot;</strong></td><td style="text-align:left;">Tạo không gian cá nhân riêng biệt của <code>hybridUser</code>, đồng bộ <code>currentAgencyId</code> sang Personal Hub mà không ảnh hưởng tới quyền <code>Creator</code> ở <code>Agency A1</code>.</td><td style="text-align:center;">☑</td></tr></tbody></table><hr><h2 id="b-chien-dich-ca-nhan-khong-can-mediapackage-tao-cong-viec-đoc-lap-8-loai-tasktype" tabindex="-1">B. Chiến dịch Cá nhân Không cần <code>MediaPackage</code> &amp; Tạo Công việc Độc lập (8 Loại <code>TaskType</code>) <a class="header-anchor" href="#b-chien-dich-ca-nhan-khong-can-mediapackage-tao-cong-viec-đoc-lap-8-loai-tasktype" aria-label="Permalink to &quot;B. Chiến dịch Cá nhân Không cần `MediaPackage` &amp; Tạo Công việc Độc lập (8 Loại `TaskType`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">ID</th><th style="text-align:left;">Map</th><th style="text-align:center;">Tầng</th><th style="text-align:left;">Bước / Input</th><th style="text-align:left;">Kết quả mong đợi</th><th style="text-align:center;">KQ</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>P-B1</strong></td><td style="text-align:left;">AC6, §7.3, T2.1</td><td style="text-align:center;">I</td><td style="text-align:left;">Trong <code>W_PERSONAL</code> (chưa từng tạo <code>MediaPackage</code>), khởi tạo bản nháp và gọi <code>deploy</code> một <code>MediaCampaign</code> gồm 5 bài <code>POST</code>, 3 <code>SHORT_VIDEO</code>, 1 <code>EVENT_PLAN</code></td><td style="text-align:left;">Khởi tạo và deploy Chiến dịch thành công, sinh đủ 9 Task với <code>requiresClientApproval = false</code>, không bị chặn bởi lỗi thiếu <code>WorkspaceMediaPackage</code> hay vượt trần số lượng gói.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-B2</strong></td><td style="text-align:left;">AC7, §3, §7.4, T2.2</td><td style="text-align:center;">I</td><td style="text-align:left;">Trong <code>W_PERSONAL</code>, gọi <code>POST /api/v1/workspaces/{id}/tasks/standalone</code> lần lượt cho cả <strong>8 loại <code>TaskType</code></strong>: <code>POST</code>, <code>SHORT_VIDEO</code>, <code>SURVEY</code>, <code>EVENT_PLAN</code>, <code>PRESS_RECOMMENDATION</code>, <code>KOL_BOOKING</code>, <code>WORKSHOP</code>, <code>EMAIL_NEWSLETTER</code> (<code>initRoleSubtasks = true</code>)</td><td style="text-align:left;">Cả 8 Task đều được tạo thành công với <code>sourceType = &quot;manual&quot;</code>, <code>requiresClientApproval = false</code>, <code>assigneeId = soloUser.id</code>, và sinh đúng số lượng Subtask vai trò theo <code>TaskCatalog</code> (POST: 5, SHORT_VIDEO: 4, SURVEY: 3, EVENT_PLAN: 5, PRESS: 4, KOL: 5, WORKSHOP: 5, EMAIL: 4).</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-B3</strong></td><td style="text-align:left;">AC7, §11.7, T2.2</td><td style="text-align:center;">I</td><td style="text-align:left;">Gọi <code>POST /tasks/standalone</code> khi <code>W_PERSONAL</code> chưa có bất kỳ <code>MediaCampaign</code> nào (<code>campaignId = null</code>)</td><td style="text-align:left;">Hệ thống tự động khởi tạo ngầm chiến dịch cá nhân mặc định và gắn Task vào, giúp Task hiển thị đầy đủ trên cả Danh sách, Lịch và Timeline.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-B4</strong></td><td style="text-align:left;">§10, T2.2</td><td style="text-align:center;">I</td><td style="text-align:left;">Gọi <code>POST /tasks/standalone</code> với <code>title = &quot;&quot;</code> hoặc <code>type</code> không hợp lệ</td><td style="text-align:left;">Trả về <code>400 Bad Request</code> (<code>VALIDATION_ERROR</code>).</td><td style="text-align:center;">☑</td></tr></tbody></table><hr><h2 id="c-co-che-tu-duyet-1-cham-solo-self-approval-mo-khoa-xuat-ban-xuat-file" tabindex="-1">C. Cơ chế Tự duyệt 1 Chạm (<code>Solo Self-Approval</code>) &amp; Mở khóa Xuất bản / Xuất File <a class="header-anchor" href="#c-co-che-tu-duyet-1-cham-solo-self-approval-mo-khoa-xuat-ban-xuat-file" aria-label="Permalink to &quot;C. Cơ chế Tự duyệt 1 Chạm (`Solo Self-Approval`) &amp; Mở khóa Xuất bản / Xuất File&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">ID</th><th style="text-align:left;">Map</th><th style="text-align:center;">Tầng</th><th style="text-align:left;">Bước / Input</th><th style="text-align:left;">Kết quả mong đợi</th><th style="text-align:center;">KQ</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>P-C1</strong></td><td style="text-align:left;">AC8, §7.5, T2.3</td><td style="text-align:center;">U+I</td><td style="text-align:left;"><code>soloUser</code> (<code>Owner</code>/<code>Manager</code> của <code>W_PERSONAL</code>) gọi <code>POST /api/v1/workspaces/{ws}/tasks/{taskId}/self-approve</code> trên Task <code>POST</code> đang ở <code>TODO</code> (kể cả khi một số <code>TaskSection</code> chưa có document trong DB — §11.8)</td><td style="text-align:left;">Toàn bộ 4 phần (<code>POST.BRIEF</code>, <code>POST.CAPTION</code>, <code>POST.MEDIA</code>, <code>POST.CHANNELS</code>) được upsert và chuyển sang <code>INTERNAL_APPROVED</code> (<code>finalState = true</code>); cả 5 Subtask chuyển sang <code>FINISHED</code>; Task cha chuyển sang <code>FINISHED</code> (<code>lastSubmission.outcome = APPROVED</code>); <code>PostDocument</code> chuyển sang <code>APPROVED</code>.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-C2</strong></td><td style="text-align:left;">§11.9, T2.3</td><td style="text-align:center;">I</td><td style="text-align:left;">Gọi lại <code>self-approve</code> lần thứ 2 trên Task đã <code>FINISHED</code> ở P-C1</td><td style="text-align:left;">Trả về <code>200 OK</code> (Idempotent), không phát sinh lỗi hay bản ghi lịch sử trùng.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-C3</strong></td><td style="text-align:left;">AC9, §10, T2.3</td><td style="text-align:center;">I</td><td style="text-align:left;"><code>teammateCreator</code> (chỉ có role <code>Creator</code>) gọi <code>self-approve</code> trong <code>W_PERSONAL</code></td><td style="text-align:left;">Bị từ chối với <code>403 Forbidden</code>.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-C4</strong></td><td style="text-align:left;">AC9, §10, T2.3</td><td style="text-align:center;">I</td><td style="text-align:left;">Trong <code>W_AGENCY</code>, <code>Manager</code> gọi <code>self-approve</code> trên một Task có <code>requiresClientApproval = true</code></td><td style="text-align:left;">Bị từ chối với <code>400 Bad Request</code> (<code>TASK_SELF_APPROVE_NOT_ALLOWED</code>).</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-C5</strong></td><td style="text-align:left;">AC10, T2.3</td><td style="text-align:center;">I</td><td style="text-align:left;">Sau khi <code>self-approve</code> Task <code>POST</code> (đã đặt <code>scheduledAt &lt;= now</code>), chạy <code>PostSchedulePublishJob</code></td><td style="text-align:left;">Job nhận diện <code>task.status == FINISHED &amp;&amp; lastSubmission.outcome == APPROVED</code> và đẩy lệnh xuất bản bài viết sang <code>publisher-service</code> thành công.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-C6</strong></td><td style="text-align:left;">AC10, T2.3</td><td style="text-align:center;">I</td><td style="text-align:left;">Sau khi <code>self-approve</code> Task <code>EMAIL_NEWSLETTER</code>, gọi <code>POST /tasks/{id}/newsletter/send</code></td><td style="text-align:left;">Gửi Newsletter thành công (do <code>EMAIL.CONTENT</code> và <code>EMAIL.DESIGN</code> đã đạt trạng thái cuối <code>INTERNAL_APPROVED</code> với <code>requiresClientApproval = false</code>).</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-C7</strong></td><td style="text-align:left;">AC10, T2.3</td><td style="text-align:center;">I</td><td style="text-align:left;">Sau khi <code>self-approve</code> Task <code>EVENT_PLAN</code> và <code>PRESS_RECOMMENDATION</code>, gọi <code>GET /tasks/{id}/export</code></td><td style="text-align:left;">Xuất file PDF (<code>EVENT_PLAN</code>) và DOCX (<code>PRESS_RECOMMENDATION</code>) thành công, <strong>không</strong> bị đóng dấu chữ <em>&quot;Bản nháp&quot;</em> vì mọi phần O đã ở trạng thái cuối (<code>isFinal = true</code>).</td><td style="text-align:center;">☑</td></tr></tbody></table><hr><h2 id="d-cong-tac-nhom-nho-study-group-small-team-mxh-ai-credit-trong-che-đo-personal" tabindex="-1">D. Cộng tác Nhóm nhỏ (<code>Study Group / Small Team</code>), MXH &amp; AI Credit trong Chế độ <code>PERSONAL</code> <a class="header-anchor" href="#d-cong-tac-nhom-nho-study-group-small-team-mxh-ai-credit-trong-che-đo-personal" aria-label="Permalink to &quot;D. Cộng tác Nhóm nhỏ (`Study Group / Small Team`), MXH &amp; AI Credit trong Chế độ `PERSONAL`&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">ID</th><th style="text-align:left;">Map</th><th style="text-align:center;">Tầng</th><th style="text-align:left;">Bước / Input</th><th style="text-align:left;">Kết quả mong đợi</th><th style="text-align:center;">KQ</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>P-D1</strong></td><td style="text-align:left;">AC14, §7.6</td><td style="text-align:center;">I</td><td style="text-align:left;"><code>soloUser</code> mời <code>teammateCreator</code> vào <code>W_PERSONAL</code> với role <code>Creator</code> và giao Subtask <code>EVENT_LOGISTICS</code></td><td style="text-align:left;"><code>teammateCreator</code> vào được trình soạn thảo <code>EventEditor</code>, sửa và bấm <code>Submit</code> phần <code>EVENT.LOGISTICS</code>; <code>soloUser</code> bấm <code>Approve</code> → phần đạt trạng thái cuối <code>INTERNAL_APPROVED</code> ngay mà không cần <code>Client</code>.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-D2</strong></td><td style="text-align:left;">AC13, §7.8, T2.4</td><td style="text-align:center;">I</td><td style="text-align:left;">Trong <code>W_PERSONAL</code>, <code>soloUser</code> (<code>Owner</code>/<code>Manager</code>) kết nối tài khoản <strong>Facebook, Instagram, TikTok, Threads</strong></td><td style="text-align:left;">Kết nối và ngắt kết nối thành công cho cả 4 nền tảng mà không yêu cầu role <code>Client</code>.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-D3</strong></td><td style="text-align:left;">§7.8, §11.10</td><td style="text-align:center;">I</td><td style="text-align:left;">Trong <code>W_PERSONAL</code>, <code>soloUser</code> hoặc <code>teammateCreator</code> gọi AI tạo Caption / Ảnh thương mại</td><td style="text-align:left;">Hệ thống trừ credit từ ví <code>agency_credit_wallets</code> của <code>Personal Hub Agency</code> và tuân thủ hạn mức <code>workspaceLimit</code> (nếu có).</td><td style="text-align:center;">☑</td></tr></tbody></table><hr><h2 id="e-giao-dien-thich-ung-adaptive-ui-quick-launchpad-trinh-xem-3-che-đo-brandhub-web" tabindex="-1">E. Giao diện Thích ứng (<code>Adaptive UI</code>), Quick Launchpad &amp; Trình xem 3 chế độ (<code>brandhub-web</code>) <a class="header-anchor" href="#e-giao-dien-thich-ung-adaptive-ui-quick-launchpad-trinh-xem-3-che-đo-brandhub-web" aria-label="Permalink to &quot;E. Giao diện Thích ứng (`Adaptive UI`), Quick Launchpad &amp; Trình xem 3 chế độ (`brandhub-web`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">ID</th><th style="text-align:left;">Map</th><th style="text-align:center;">Tầng</th><th style="text-align:left;">Bước / Input</th><th style="text-align:left;">Kết quả mong đợi</th><th style="text-align:center;">KQ</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>P-E1</strong></td><td style="text-align:left;">AC11, T4.1</td><td style="text-align:center;">E</td><td style="text-align:left;">Mở <code>W_PERSONAL</code> và kiểm tra thanh <code>Sidebar</code></td><td style="text-align:left;">Thanh Tiến trình ẩn bước <code>1. Gói dịch vụ</code>, hiển thị 2 bước mở sẵn (<code>1. Kế hoạch &amp; Chiến dịch</code>, <code>2. Công việc &amp; Sáng tạo</code>); menu ẩn <code>/clients</code>, <code>/client-profile</code>, <code>/portal</code>, <code>/requests</code>.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-E2</strong></td><td style="text-align:left;">AC12, T4.2</td><td style="text-align:center;">E</td><td style="text-align:left;">Mở <code>/workspaces/{W_PERSONAL}/dashboard</code></td><td style="text-align:left;">Không hiển thị <code>PackageStatusBanner</code>; hiển thị khối <strong>Bệ phóng Sáng tạo Cá nhân (<code>Personal Quick Launchpad</code>)</strong> gồm 5 lối tắt hành động nhanh.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-E3</strong></td><td style="text-align:left;">AC7, T4.4</td><td style="text-align:center;">E</td><td style="text-align:left;">Bấm <strong>&quot;+ Tạo công việc mới&quot;</strong> tại <code>/workspaces/{W_PERSONAL}/tasks</code> hoặc từ <code>Personal Quick Launchpad</code> → chọn loại công việc → bấm <strong>&quot;Tạo &amp; Mở trình soạn thảo&quot;</strong></td><td style="text-align:left;">Mở <code>QuickCreateTaskDialog</code> với đủ 8 loại <code>TaskType</code>, tạo Task thành công và điều hướng thẳng vào trình soạn thảo tương ứng.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-E4</strong></td><td style="text-align:left;">AC8, T4.5</td><td style="text-align:center;">E</td><td style="text-align:left;">Trong chi tiết Task hoặc trình soạn thảo của <code>W_PERSONAL</code>, bấm nút <strong>&quot;Hoàn tất &amp; Duyệt ngay&quot;</strong></td><td style="text-align:left;">Task chuyển ngay sang trạng thái <code>Hoàn tất (Finished)</code> kèm thông báo thành công và mở khóa nút Đăng bài / Lên lịch / Xuất file.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-E5</strong></td><td style="text-align:left;">AC15, T4.6</td><td style="text-align:center;">E</td><td style="text-align:left;">Tại trang Danh sách công việc, mở chi tiết Task lần lượt ở 3 chế độ: <code>Side Peek</code>, <code>Center Modal</code>, <code>Full Page</code></td><td style="text-align:left;">Panel mở mượt mà chỉ 1 lần (không bị giật phóng ra – thu vào – phóng ra lại), lớp nền phía dưới được làm mờ nhẹ (<code>backdrop-blur-[2px]</code>) giúp tập trung vào nội dung.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-E6</strong></td><td style="text-align:left;">AC16, T5.4</td><td style="text-align:center;">M</td><td style="text-align:left;">Mở ứng dụng di động (<code>brandhub-mobile-app</code>) trên tài khoản có <code>W_PERSONAL</code></td><td style="text-align:left;">Hiển thị đúng nhãn <code>Cá nhân</code> / <code>Personal</code> và cho phép xem/duyệt công việc không lỗi.</td><td style="text-align:center;">☑</td></tr></tbody></table><hr><h2 id="f-đa-ngon-ngu-vi-en-giao-dien-sang-toi-light-dark-responsive" tabindex="-1">F. Đa ngôn ngữ (<code>vi</code>/<code>en</code>), Giao diện Sáng/Tối (<code>Light/Dark</code>) &amp; Responsive <a class="header-anchor" href="#f-đa-ngon-ngu-vi-en-giao-dien-sang-toi-light-dark-responsive" aria-label="Permalink to &quot;F. Đa ngôn ngữ (`vi`/`en`), Giao diện Sáng/Tối (`Light/Dark`) &amp; Responsive&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">ID</th><th style="text-align:left;">Map</th><th style="text-align:center;">Tầng</th><th style="text-align:left;">Bước / Input</th><th style="text-align:left;">Kết quả mong đợi</th><th style="text-align:center;">KQ</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>P-F1</strong></td><td style="text-align:left;">AC17, §13, T5.1</td><td style="text-align:center;">U</td><td style="text-align:left;">So khớp toàn bộ khóa mới trong <code>src/i18n/locales/vi/{workspace,agency,tasks,nav}.json</code> và <code>en/{workspace,agency,tasks,nav}.json</code></td><td style="text-align:left;">Khớp 100% key-parallel giữa <code>vi</code> và <code>en</code>, không thiếu bất kỳ khóa nào trong bảng <code>spec.md §13</code>.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-F2</strong></td><td style="text-align:left;">AC17, T5.2</td><td style="text-align:center;">T</td><td style="text-align:left;">Chuyển đổi ngôn ngữ <code>VI ↔ EN</code> trên các trang <code>/agency</code>, <code>/workspace/create</code>, <code>/workspaces/:id/dashboard</code>, <code>/workspaces/:id/tasks</code>, <code>/workspaces/:id/settings</code></td><td style="text-align:left;">Mọi nhãn hiển thị đúng ngôn ngữ đã chọn, không lộ raw key, không có chuỗi hardcode.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-F3</strong></td><td style="text-align:left;">AC18, T5.3</td><td style="text-align:center;">T</td><td style="text-align:left;">Kiểm tra giao diện <strong>Light Mode</strong> và <strong>Dark Mode</strong> trên <code>375px</code> (Mobile), <code>768px</code> (Tablet), <code>1440px</code> (Desktop)</td><td style="text-align:left;">Tương phản chữ đạt chuẩn WCAG AA, không có màu hex lạc tông, không bị tràn ngang ở mọi kích thước màn hình.</td><td style="text-align:center;">☑</td></tr><tr><td style="text-align:left;"><strong>P-F4</strong></td><td style="text-align:left;">§14, T6.1</td><td style="text-align:center;">I+E</td><td style="text-align:left;">Chạy <code>mvn test</code> (<code>brandhub-business-service</code>) và <code>npm run type-check &amp;&amp; npm test -- --run &amp;&amp; npx vite build</code> (<code>brandhub-web</code>)</td><td style="text-align:left;">Toàn bộ lệnh kiểm tra và build đạt kết quả PASS 100%.</td><td style="text-align:center;">☑</td></tr></tbody></table><hr><h2 id="ket-qua-chay-kiem-thu" tabindex="-1">Kết quả Chạy Kiểm thử <a class="header-anchor" href="#ket-qua-chay-kiem-thu" aria-label="Permalink to &quot;Kết quả Chạy Kiểm thử&quot;">​</a></h2><ul><li><strong>Backend (<code>brandhub-business-service</code>)</strong>: <ul><li>Lệnh: <code>mvn test -Dtest=&quot;WorkspaceSettingsHelperTest,PersonalWorkspaceBootstrapTest,PersonalTaskWorkflowTest,WorkspaceServiceTest&quot;</code></li><li>Kết quả: <strong><code>BUILD SUCCESS — Tests run: 65, Failures: 0, Errors: 0, Skipped: 0</code></strong>.</li></ul></li><li><strong>Frontend (<code>brandhub-web</code>)</strong>: <ul><li>Lệnh: <code>npm run type-check &amp;&amp; npx vitest run src/hooks/__tests__/useWorkspaceMode.test.tsx &amp;&amp; npx vite build</code></li><li>Kết quả: <ul><li><code>npm run type-check</code>: <strong><code>0 errors</code></strong> (<code>tsconfig.app.json</code> &amp; <code>tsconfig.node.json</code>).</li><li><code>vitest run src/hooks/__tests__/useWorkspaceMode.test.tsx</code>: <strong><code>1 passed (4 tests)</code></strong>.</li><li><code>npx vite build</code>: <strong><code>✓ built in 3.19s</code> (<code>6034 modules transformed</code>)</strong>.</li></ul></li></ul></li></ul>',26)])])}const u=e(c,[["render",l]]);export{y as __pageData,u as default};
